    '"my years at yahaya international completely transformed my worldview. the attention to detail in the curriculum and the ease of access to mentors allowed me to maintain my faith identity while delivering world-class academic performance. it\'s not just a school; it\'s a competitive advantage."': '"سنواتي في يهايا الدولية غيرت نظرتي للعالم تمامًا. إن الاهتمام بالتفاصيل في المناهج الدراسية وسهولة الوصول إلى الموجهين سمح لي بالحفاظ على هويتي الإيمانية مع تقديم أداء أكاديمي عالمي المستوى. إنها ليست مجرد مدرسة؛ إنها ميزة تنافسية."',
    '"science without conscience is but the ruin of the soul. at yahaya, we ensure our students understand that every technological advancement must serve humanity and preserve our planet."': '"العلم بدون ضمير ما هو إلا خراب للروح. في يهايا، نحرص على أن يفهم طلابنا أن كل تقدم تكنولوجي يجب أن يخدم البشرية ويحافظ على كوكبنا."',
    '"since enrolling our daughter at yahaya international, we have seen remarkable growth not just in her academic performance but in her character. the seamless integration of islamic values with rigorous modern education is exactly what we were looking for."': '"منذ تسجيل ابنتنا في يهايا الدولية، شهدنا نموًا ملحوظًا ليس فقط في أدائها الأكاديمي بل في شخصيتها. إن الدمج السلس للقيم الإسلامية مع التعليم الحديث الصارم هو بالضبط ما كنا نبحث عنه."',
    '"the leadership at yahaya international demonstrates a profound commitment to educational excellence. i have witnessed firsthand how they nurture students into well-rounded individuals ready to tackle global challenges with moral integrity."': '"تُظهر القيادة في يهايا الدولية التزامًا عميقًا بالتميز التعليمي. لقد شهدت بنفسي كيف يربون الطلاب ليصبحوا أفرادًا متكاملين مستعدين لمواجهة التحديات العالمية بنزاهة أخلاقية."',
    '"we evaluated many schools before choosing yahaya international. the facilities are modern, the teachers are highly qualified, and the emphasis on both d\'awah and stem makes it a unique and invaluable environment for our children."': '"لقد قمنا بتقييم العديد من المدارس قبل اختيار يهايا الدولية. المرافق حديثة، والمعلمون مؤهلون تأهيلاً عالياً، والتركيز على كل من الدعوة والعلوم والتكنولوجيا والهندسة والرياضيات يجعلها بيئة فريدة ولا تقدر بثمن لأطفالنا."',
    '#sciencefair2024,#studentexcellence,#innovation,#yahayainternational': '#معرض_العلوم_2024,#تميز_الطلاب,#الابتكار,#يهايا_الدولية',
