    'a full immersion in classical and modern arabic, giving students the confidence to read primary sources and hold a conversation with equal ease.': 'انغماس كامل في اللغة العربية الفصحى والحديثة، مما يمنح الطلاب الثقة لقراءة المصادر الأولية وإجراء محادثة بنفس السهولة.',
    'a grounding in fiqh, aqeedah, and seerah that gives students a coherent worldview and the tools to reason within it.': 'أساس في الفقه والعقيدة والسيرة يمنح الطلاب رؤية عالمية متماسكة وأدوات للتفكير داخلها.',
    'a pivotal year marked by our recognition as a leading global institution. we converged knowledge and faith, cultivating future leaders who advocate for justice, embody empathy, and drive positive change in their communities worldwide.': 'عام محوري تميز باعترافنا كمؤسسة عالمية رائدة. قمنا بدمج المعرفة والإيمان، وزرع قادة المستقبل الذين يدافعون عن العدالة، ويجسدون التعاطف، ويدفعون التغيير الإيجابي في مجتمعاتهم في جميع أنحاء العالم.',
    'a supportive network of educators, parents, and alumni.': 'شبكة داعمة من المعلمين وأولياء الأمور والخريجين.',
    'a teacher leading a class discussion': 'معلم يقود مناقشة في الفصل',
