    'at yahaya international, we blend the prestige of global academic rigor with deep-rooted spiritual leadership. our faculty members are more than educators; they are mentors, researchers, and stewards of wisdom dedicated to shaping the leaders of tomorrow.': 'في يهايا الدولية، نمزج بين هيبة الصرامة الأكاديمية العالمية والقيادة الروحية العميقة. أعضاء هيئة التدريس لدينا هم أكثر من مجرد معلمين؛ إنهم مرشدون وباحثون وحراس حكمة مكرسون لتشكيل قادة الغد.',
