    'visit our campus, meet our students and faculty, and see how we nurture excellence in both faith and knowledge.': 'قم بزيارة حرمنا الجامعي، وتعرف على طلابنا وأعضاء هيئة التدريس، واكتشف كيف نرعى التميز في كل من الإيمان والمعرفة.',
