    'warning': 'تحذير',
    'we are thrilled to announce the opening of our newest innovation hub, designed to foster...': 'يسعدنا أن نعلن عن افتتاح أحدث مركز ابتكار لدينا، والمصمم لتعزيز...',
    'we doubled our teaching faculty and completed the integration of the international curriculum with our qur\'anic and arabic programmes, establishing the dual-track model the school is known for today.': 'ضاعفنا هيئة التدريس لدينا وأكملنا دمج المناهج الدولية مع برامجنا القرآنية والعربية، وإنشاء النموذج المزدوج المسار الذي تعرف به المدرسة اليوم.',
    'we recognised a growing need for an educational model that does not force families to choose between modern excellence and faith-based values. here, they are seamlessly integrated. our students are challenged intellectually while being supported emotionally and spiritually.': 'لقد أدركنا الحاجة المتزايدة لنموذج تعليمي لا يجبر العائلات على الاختيار بين التميز الحديث والقيم القائمة على الإيمان. هنا، يتم دمجها بسلاسة. يتم تحدي طلابنا فكريًا بينما يتم دعمهم عاطفيًا وروحيًا.',
    'we\'re here to answer your questions and guide your child\'s educational journey towards modern islamic excellence.': 'نحن هنا للإجابة على أسئلتك وتوجيه رحلة طفلك التعليمية نحو التميز الإسلامي الحديث.',
    'website': 'الموقع الإلكتروني',
    'welcome back': 'مرحباً بعودتك',
    'welcome back, {name}': 'مرحباً، {name}',
    'welcome to yahaya international. when we established this institution in 2020, our goal was simple yet profound: to create an environment where academic rigour meets spiritual depth.': 'مرحبًا بكم في يهايا الدولية. عندما أسسنا هذه المؤسسة في عام 2020، كان هدفنا بسيطًا ولكنه عميق: خلق بيئة يلتقي فيها الصرامة الأكاديمية بالعمق الروحي.',
    'whatsapps us': 'راسلنا على واتساب',
    'where your': 'أين يذهب',
    'why choose yahaya international?': 'لماذا تختار يهايا الدولية؟',
    'worker': 'موظف دعم',
    'workers': 'موظفو الخدمات',
    'yahaya international islamic & english high school is more than just an educational institution': 'مدرسة يهايا الدولية الإسلامية والإنجليزية هي أكثر من مجرد مؤسسة تعليمية',
    'yahaya international islamic & english high school is more than just an educational institution; it is a community dedicated to shaping the holistic development of every child. we bridge the gap between traditional islamic ethics and modern western education.': 'مدرسة يهايا الدولية الإسلامية والإنجليزية هي أكثر من مجرد مؤسسة تعليمية؛ إنها مجتمع مكرس لتشكيل التنمية الشاملة لكل طفل. نحن نسد الفجوة بين الأخلاق الإسلامية التقليدية والتعليم الغربي الحديث.',
    'yahaya international islamic & english school blends the depth of traditional islamic values with the rigorous standards of modern international education, fostering a nurturing environment for holistic student growth.': 'تمزج مدرسة يهايا الدولية الإسلامية والإنجليزية بين عمق القيم الإسلامية التقليدية والمعايير الصارمة للتعليم الدولي الحديث، مما يعزز بيئة حاضنة للنمو الشامل للطلاب.',
    'yahaya international islamic and english high school': 'مدرسة يهايا الدولية الإسلامية والإنجليزية الثانوية',
    'yahaya international opened its doors with a founding cohort and a simple conviction: that rigorous academics and islamic character formation belong in the same classroom, not in competition with one another.': 'فتحت يهايا الدولية أبوابها بفرقة تأسيسية وقناعة بسيطة: أن الأكاديميين الصارمين وتشكيل الشخصية الإسلامية ينتمون إلى نفس الفصل الدراسي، وليس في منافسة مع بعضهم البعض.',
    'yahaya international\'s qur\'an memorization & hifz program offers a scholarly environment where spiritual devotion meets academic rigor, nurturing tomorrow\'s leaders through the wisdom of the holy qur\'an.': 'يقدم برنامج تحفيظ القرآن الكريم في أكاديمية يحيى الدولية بيئة علمية حيث يلتقي الإخلاص الروحي مع الصرامة الأكاديمية، لتربية قادة الغد من خلال حكمة القرآن الكريم.',
    'years': 'سنوات',
    'yes': 'نعم',
    'yesterday': 'أمس',
    'your account has been disabled. contact the administrator.': 'تم تعطيل حسابك. تواصل مع المسؤول.',
    'your contribution nurtures faith, knowledge, and character. together, we can provide a world-class islamic and modern education for every child.': 'مساهمتك تغذي الإيمان والمعرفة والشخصية. معاً، يمكننا توفير تعليم إسلامي وحديث عالمي المستوى لكل طفل.',
    'your donation is processed securely.': 'تتم معالجة تبرعك بأمان.',
    'your enrollment has been submitted and is under review. you will receive a confirmation email shortly.': 'تم إرسال تسجيلك وهو قيد المراجعة. ستتلقى رسالة تأكيد بالبريد الإلكتروني قريبًا.',
