    '"my years at yahaya international completely transformed my worldview. the attention to detail in the curriculum and the ease of access to mentors allowed me to maintain my faith identity while delivering world-class academic performance. it\'s not just a school; it\'s a competitive advantage."': '"Mes années à Yahaya International ont complètement transformé ma vision du monde. L\'attention portée aux détails dans le programme et la facilité d\'accès aux mentors m\'ont permis de maintenir mon identité de foi tout en offrant des performances académiques de classe mondiale. Ce n\'est pas seulement une école ; c\'est un avantage concurrentiel."',
    '"science without conscience is but the ruin of the soul. at yahaya, we ensure our students understand that every technological advancement must serve humanity and preserve our planet."': '"Science sans conscience n\'est que ruine de l\'âme. À Yahaya, nous veillons à ce que nos étudiants comprennent que chaque avancée technologique doit servir l\'humanité et préserver notre planète."',
    '"since enrolling our daughter at yahaya international, we have seen remarkable growth not just in her academic performance but in her character. the seamless integration of islamic values with rigorous modern education is exactly what we were looking for."': '"Depuis l\'inscription de notre fille à Yahaya International, nous avons constaté une croissance remarquable non seulement dans ses résultats académiques, mais aussi dans son caractère. L\'intégration harmonieuse des valeurs islamiques avec une éducation moderne rigoureuse est exactement ce que nous recherchions."',
    '"the leadership at yahaya international demonstrates a profound commitment to educational excellence. i have witnessed firsthand how they nurture students into well-rounded individuals ready to tackle global challenges with moral integrity."': '"La direction de Yahaya International fait preuve d\'un profond engagement envers l\'excellence éducative. J\'ai été témoin de première main de la façon dont ils nourrissent les élèves pour en faire des individus équilibrés prêts à relever des défis mondiaux avec une intégrité morale."',
    '"we evaluated many schools before choosing yahaya international. the facilities are modern, the teachers are highly qualified, and the emphasis on both d\'awah and stem makes it a unique and invaluable environment for our children."': '"Nous avons évalué de nombreuses écoles avant de choisir Yahaya International. Les installations sont modernes, les enseignants sont hautement qualifiés, et l\'accent mis à la fois sur la Da\'wah et les STEM en fait un environnement unique et inestimable pour nos enfants."',
