    'a pivotal year marked by our recognition as a leading global institution. we converged knowledge and faith, cultivating future leaders who advocate for justice, embody empathy, and drive positive change in their communities worldwide.': 'Une année charnière marquée par notre reconnaissance en tant qu\'institution mondiale de premier plan. Nous avons convergé les connaissances et la foi, cultivant les futurs dirigeants qui défendent la justice, incarnent l\'empathie et conduisent des changements positifs dans leurs communautés du monde entier.',
