    'as we look forward to the next semester, the school plans to integrate the winning water filtration project into our standard facilities, providing a tangible legacy for this year\'s participants. we congratulate all students for their hard work and dedication to excellence.': 'Alors que nous attendons avec impatience le prochain semestre, l\'école prévoit d\'intégrer le projet de filtration d\'eau gagnant dans nos installations standard, offrant ainsi un héritage tangible aux participants de cette année. Nous félicitons tous les élèves pour leur travail acharné et leur dévouement à l\'excellence.',
    'as you explore our community, you will find a dedicated faculty, state-of-the-art facilities, and most importantly, a vibrant student body eager to learn, practise and advocate for a better world.': 'Au fur et à mesure que vous explorerez notre communauté, vous trouverez un corps professoral dévoué, des installations de pointe et, surtout, un corps étudiant dynamique désireux d\'apprendre, de pratiquer et de plaider pour un monde meilleur.',
