    'asset': 'Actif',
    'at yahaya international, we blend centuries of islamic wisdom with modern academic rigor. we seek visionary educators and staff who are committed to nurturing the next generation of global leaders.': 'À Yahaya International, nous allions des siècles de sagesse islamique à la rigueur académique moderne. Nous recherchons des éducateurs et du personnel visionnaires engagés à former la prochaine génération de leaders mondiaux.',
    'at yahaya international, we blend the prestige of global academic rigor with deep-rooted spiritual leadership. our faculty members are more than educators; they are mentors, researchers, and stewards of wisdom dedicated to shaping the leaders of tomorrow.': 'Chez Yahaya International, nous allions le prestige de la rigueur académique mondiale à un profond leadership spirituel. Les membres de notre faculté sont plus que des éducateurs; ils sont des mentors, des chercheurs et des gardiens de la sagesse dédiés à former les leaders de demain.',
