    'visit our campus, meet our students and faculty, and see how we nurture excellence in both faith and knowledge.': 'Visitez notre campus, rencontrez nos étudiants et notre corps professoral, et voyez comment nous cultivons l\'excellence dans la foi et la connaissance.',
