    'we are thrilled to announce the opening of our newest innovation hub, designed to foster...': 'Nous sommes ravis d\'annoncer l\'ouverture de notre tout dernier pôle d\'innovation, conçu pour favoriser...',
    'we doubled our teaching faculty and completed the integration of the international curriculum with our qur\'anic and arabic programmes, establishing the dual-track model the school is known for today.': 'Nous avons doublé notre corps enseignant et achevé l\'intégration du programme international avec nos programmes coraniques et arabes, établissant le modèle à double voie pour lequel l\'école est connue aujourd\'hui.',
    'we recognised a growing need for an educational model that does not force families to choose between modern excellence and faith-based values. here, they are seamlessly integrated. our students are challenged intellectually while being supported emotionally and spiritually.': 'Nous avons reconnu le besoin croissant d\'un modèle éducatif qui n\'oblige pas les familles à choisir entre l\'excellence moderne et les valeurs fondées sur la foi. Ici, ils s\'intègrent parfaitement. Nos étudiants sont mis au défi intellectuellement tout en étant soutenus émotionnellement et spirituellement.',
    'we\'re here to answer your questions and guide your child\'s educational journey towards modern islamic excellence.': 'Nous sommes là pour répondre à vos questions et guider le parcours éducatif de votre enfant vers l\'Excellence Islamique Moderne.',
    'website': 'Site web',
    'welcome back': 'Bon retour',
    'welcome back, {name}': 'Bienvenue, {name}',
    'welcome to yahaya international. when we established this institution in 2020, our goal was simple yet profound: to create an environment where academic rigour meets spiritual depth.': 'Bienvenue à Yahaya International. Lorsque nous avons créé cette institution en 2020, notre objectif était simple mais profond : créer un environnement où la rigueur académique rencontre la profondeur spirituelle.',
    'whatsapps us': 'Contactez-nous sur WhatsApp',
    'where your': 'Où Va',
    'why choose yahaya international?': 'Pourquoi Choisir Yahaya International ?',
    'worker': 'Agent de soutien',
    'workers': 'Personnel de soutien',
    'yahaya international islamic & english high school is more than just an educational institution': 'L\'école secondaire internationale islamique et anglaise Yahaya est plus qu\'une simple institution éducative',
    'yahaya international islamic & english high school is more than just an educational institution; it is a community dedicated to shaping the holistic development of every child. we bridge the gap between traditional islamic ethics and modern western education.': 'L\'école secondaire internationale islamique et anglaise Yahaya est plus qu\'une simple institution éducative ; c\'est une communauté dédiée au développement holistique de chaque enfant. Nous comblons le fossé entre l\'éthique islamique traditionnelle et l\'éducation occidentale moderne.',
    'yahaya international islamic & english school blends the depth of traditional islamic values with the rigorous standards of modern international education, fostering a nurturing environment for holistic student growth.': 'L\'école internationale islamique et anglaise Yahaya allie la profondeur des valeurs islamiques traditionnelles aux normes rigoureuses de l\'éducation internationale moderne, favorisant un environnement stimulant pour la croissance holistique des étudiants.',
    'yahaya international islamic and english high school': 'École Secondaire Islamique et Anglaise Internationale Yahaya',
    'yahaya international opened its doors with a founding cohort and a simple conviction: that rigorous academics and islamic character formation belong in the same classroom, not in competition with one another.': 'Yahaya International a ouvert ses portes avec une cohorte fondatrice et une conviction simple : que les universitaires rigoureux et la formation du caractère islamique appartiennent à la même classe, pas en concurrence les uns avec les autres.',
    'yahaya international\'s qur\'an memorization & hifz program offers a scholarly environment where spiritual devotion meets academic rigor, nurturing tomorrow\'s leaders through the wisdom of the holy qur\'an.': 'Le programme de mémorisation du Coran et de Hifz de Yahaya International offre un cadre d\'étude où la dévotion spirituelle rencontre la rigueur académique.',
