    'your contribution nurtures faith, knowledge, and character. together, we can provide a world-class islamic and modern education for every child.': 'Votre contribution nourrit la foi, la connaissance et le caractère. Ensemble, nous pouvons offrir une éducation islamique et moderne de classe mondiale à chaque enfant.',
