    '"my years at yahaya international completely transformed my worldview. the attention to detail in the curriculum and the ease of access to mentors allowed me to maintain my faith identity while delivering world-class academic performance. it\'s not just a school; it\'s a competitive advantage."': '"Yahaya International\'daki yıllarım dünya görüşümü tamamen değiştirdi. Müfredattaki detaylara verilen önem ve mentorlara erişim kolaylığı, dünya standartlarında akademik performans sunarken inanç kimliğimi korumamı sağladı. Bu sadece bir okul değil; rekabet avantajı."',
    '"science without conscience is but the ruin of the soul. at yahaya, we ensure our students understand that every technological advancement must serve humanity and preserve our planet."': '"Vicdansız bilim, ruhun yıkımından başka bir şey değildir. Yahaya\'da öğrencilerimizin her teknolojik ilerlemenin insanlığa hizmet etmesi ve gezegenimizi koruması gerektiğini anlamalarını sağlıyoruz."',
    '"since enrolling our daughter at yahaya international, we have seen remarkable growth not just in her academic performance but in her character. the seamless integration of islamic values with rigorous modern education is exactly what we were looking for."': '"Kızımızı Yahaya International\'a kaydettirdiğimizden beri, sadece akademik performansında değil, karakterinde de dikkate değer bir büyüme gördük. İslami değerlerin titiz modern eğitimle kusursuz entegrasyonu tam olarak aradığımız şeydi."',
    '"the leadership at yahaya international demonstrates a profound commitment to educational excellence. i have witnessed firsthand how they nurture students into well-rounded individuals ready to tackle global challenges with moral integrity."': '"Yahaya International\'daki liderlik, eğitim mükemmelliğine derin bir bağlılık göstermektedir. Öğrencileri ahlaki dürüstlükle küresel zorluklarla başa çıkmaya hazır çok yönlü bireyler olarak nasıl yetiştirdiklerine ilk elden tanık oldum."',
    '"we evaluated many schools before choosing yahaya international. the facilities are modern, the teachers are highly qualified, and the emphasis on both d\'awah and stem makes it a unique and invaluable environment for our children."': '"Yahaya International\'ı seçmeden önce birçok okulu değerlendirdik. Tesisler modern, öğretmenler son derece kalifiye ve hem Da\'wah hem de STEM\'e verilen önem burayı çocuklarımız için eşsiz ve paha biçilmez bir ortam haline getiriyor."',
