    'a full immersion in classical and modern arabic, giving students the confidence to read primary sources and hold a conversation with equal ease.': 'A full immersion in classical and modern Arabic, giving students the confidence to read primary sources and hold a conversation with equal ease.',
    'a grounding in fiqh, aqeedah, and seerah that gives students a coherent worldview and the tools to reason within it.': 'A grounding in Fiqh, Aqeedah, and Seerah that gives students a coherent worldview and the tools to reason within it.',
    'a pivotal year marked by our recognition as a leading global institution. we converged knowledge and faith, cultivating future leaders who advocate for justice, embody empathy, and drive positive change in their communities worldwide.': 'Önde gelen küresel bir kurum olarak tanınmamızla damgasını vuran çok önemli bir yıl. Adaleti savunan, empatiyi somutlaştıran ve dünya çapındaki topluluklarında olumlu değişimi yönlendiren geleceğin liderlerini yetiştirerek bilgi ve inancı bir araya getirdik.',
