    'articulation and rhythm taught from first principles, corrected one to one.': 'Articulation and rhythm taught from first principles, corrected one to one.',
    'arts & creativity': 'Sanat ve Yaratıcılık',
    'as we look forward to the next semester, the school plans to integrate the winning water filtration project into our standard facilities, providing a tangible legacy for this year\'s participants. we congratulate all students for their hard work and dedication to excellence.': 'Gelecek dönemi dört gözle beklerken, okul kazanan su filtreleme projesini standart tesislerimize entegre etmeyi planlıyor ve bu yılki katılımcılar için somut bir miras sağlıyor. Tüm öğrencileri sıkı çalışmaları ve mükemmelliğe olan bağlılıkları için tebrik ediyoruz.',
    'as you explore our community, you will find a dedicated faculty, state-of-the-art facilities, and most importantly, a vibrant student body eager to learn, practise and advocate for a better world.': 'Topluluğumuzu keşfettikçe, kendini adamış bir öğretim üyesi kadrosu, son teknoloji tesisler ve en önemlisi, daha iyi bir dünya için öğrenmeye, pratik yapmaya ve savunuculuk yapmaya hevesli canlı bir öğrenci topluluğu bulacaksınız.',
