    'asset': 'Demirbaş',
    'at yahaya international, we blend centuries of islamic wisdom with modern academic rigor. we seek visionary educators and staff who are committed to nurturing the next generation of global leaders.': 'Yahaya International\'da, yüzyıllar süren İslami bilgeliği modern akademik zorluklarla harmanlıyoruz. Gelecek nesil küresel liderleri yetiştirmeye kararlı vizyon sahibi eğitimciler ve personel arıyoruz.',
    'at yahaya international, we blend the prestige of global academic rigor with deep-rooted spiritual leadership. our faculty members are more than educators; they are mentors, researchers, and stewards of wisdom dedicated to shaping the leaders of tomorrow.': 'Yahaya International\'da, küresel akademik titizliğin prestijini derin köklü ruhsal liderlikle harmanlıyoruz. Öğretim üyelerimiz eğitimcilerden daha fazlasıdır; onlar, yarının liderlerini yetiştirmeye adanmış mentorlar, araştırmacılar ve bilgeliğin koruyucularıdır.',
