/**
 * Translate a key string dynamically based on locale with fallback to English.
 */
export function t(key: string | undefined | null, locale: string = 'en'): string {
  if (!key) return '';
  const loc = (locale || 'en').toLowerCase();
  if (loc === 'en') return key;

  const langDict = i18nDict[loc as 'ar' | 'fr' | 'tr'];
  if (!langDict) return key;

  const trimmed = key.trim();
  const normalizedKey = trimmed.toLowerCase().replace(/\s+/g, ' ');

  // 1. Direct match
  if (langDict[normalizedKey]) return langDict[normalizedKey];
  if (langDict[normalizedKey.replace(/\.$/, '')]) return langDict[normalizedKey.replace(/\.$/, '')];

  // 2. Trailing colon handling (e.g., "Year:" -> t("Year") + ":")
  if (trimmed.endsWith(':')) {
    const withoutColon = trimmed.slice(0, -1).trim();
    const trans = t(withoutColon, locale);
    if (trans !== withoutColon) return loc === 'ar' ? `${trans}:` : `${trans}:`;
  }

  // 3. Leading number handling (e.g., "1. Income Statement (P&L)" -> "1. " + t(...))
  const numPrefixMatch = trimmed.match(/^(\d+[.)]\s*)(.+)$/);
  if (numPrefixMatch) {
    const prefix = numPrefixMatch[1];
    const rest = numPrefixMatch[2];
    const transRest = t(rest, locale);
    if (transRest !== rest) return `${prefix}${transRest}`;
  }

  // 4. Trailing Currency Suffix handling (e.g., "Institutional Net Surplus (P&L) (USD)" -> t(...) + " (USD)")
  const currSuffixMatch = trimmed.match(/^(.+?)\s*\(([A-Z]{3}|\$|€|£|₺|FG|CFA|﷼)\)$/i);
  if (currSuffixMatch) {
    const baseText = currSuffixMatch[1].trim();
    const curr = currSuffixMatch[2];
    const transBase = t(baseText, locale);
    if (transBase !== baseText) return `${transBase} (${curr})`;
  }

  return key;
}

export default t;
